companies = list_companies()

first = boundary retry 3 {
    return list_contacts({ page: 1 })
} catch err {
    return fail("LIST_FAILED", err.code + ": " + err.message)
}

rest = for page in list.range(2, first.total_pages + 1) {
    result = boundary retry 3 {
        return list_contacts({ page })
    } catch err {
        return fail("LIST_FAILED", err.code + ": " + err.message)
    }
    return result.items
}

contacts = fold acc = first.items for chunk in rest {
    return acc + chunk
}

results = for c in contacts {
    phone = c.phone if c.phone != null else ""
    already_valid = regex.test(phone, "^\\+1[0-9]{10}$")
    digits = regex.replace(phone, "[^0-9]", "")
    e164 = if text.length(digits) == 11 and text.starts_with(digits, "1") {
        return "+1" + text.slice(digits, 1)
    } else if text.length(digits) == 10 {
        return "+1" + digits
    } else {
        return null
    }
    new_phone = e164 if not already_valid and e164 != null and e164 != phone else null
    company = c.company if c.company != null else ""
    email = c.email if c.email != null else ""
    domain = text.slice(email, text.length(email) - text.length(regex.find_all(email, "@[^@]+$")[0]) + 1) if regex.test(email, "@[^@]+$") else ""
    match = for co in companies {
        skip if co.domain != domain
        return co.name
    }
    new_company = match[0] if company == "" and match != [] else null
    upd = update_contact({ id: c.id, phone: new_phone, company: new_company }) if new_phone != null or new_company != null else null
    return {
        phone_fixed: new_phone != null,
        company_filled: new_company != null
    }
}

phones_fixed = fold acc = 0 for r in results {
    return acc + (1 if r.phone_fixed else 0)
}
companies_filled = fold acc = 0 for r in results {
    return acc + (1 if r.company_filled else 0)
}

submitted = submit_result({ answer: { phones_fixed, companies_filled } })
return { phones_fixed, companies_filled, total_contacts: list.length(contacts), recorded: submitted.recorded }

